import java.util.UUID

@Entity data class Product(@PrimaryKey val id: String = UUID.randomUUID().toString(), val name: String, val sku: String, val category: String, val quantity: Int, val cost: Double, val sellingPrice: Double, val lowStockAt: Int = 5)
@Entity data class Movement(@PrimaryKey val id: String = UUID.randomUUID().toString(), val productName: String, val delta: Int, val note: String, val timestamp: Long = System.currentTimeMillis())
@Dao interface StockDao { @Query("SELECT * FROM Product ORDER BY name") fun products(): Flow<List<Product>>; @Query("SELECT * FROM Movement ORDER BY timestamp DESC LIMIT 8") fun movements(): Flow<List<Movement>>; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun save(p: Product); @Insert suspend fun movement(m: Movement); @Query("SELECT COUNT(*) FROM Product") suspend fun count(): Int }
@Database(entities=[Product::class, Movement::class], version=1) abstract class StockDb: RoomDatabase(){ abstract fun dao(): StockDao }
class StockRepository(private val dao: StockDao) { val products=dao.products(); val movements=dao.movements(); suspend fun seed(){ if(dao.count()==0) listOf(Product(name="Arabica Beans",sku="BEAN-01",category="Coffee",quantity=24,cost=18.0,sellingPrice=30.0),Product(name="Paper Cups",sku="CUP-12",category="Supplies",quantity=4,cost=.18,sellingPrice=.45),Product(name="Green Tea",sku="TEA-03",category="Beverages",quantity=16,cost=9.0,sellingPrice=16.0)).forEach{dao.save(it)} }; suspend fun add(name:String,sku:String,cat:String,cost:Double,price:Double){ dao.save(Product(name=name,sku=sku,category=cat,quantity=0,cost=cost,sellingPrice=price)) }; suspend fun adjust(p:Product,delta:Int){ if(p.quantity+delta<0) return; dao.save(p.copy(quantity=p.quantity+delta)); dao.movement(Movement(productName=p.name,delta=delta,note=if(delta>0)"Incoming stock" else "Outgoing stock")) } }
data class StockState(val products:List<Product> = emptyList(), val movements:List<Movement> = emptyList(), val query:String="", val category:String="All")
class StockViewModel(app:Application): AndroidViewModel(app){ private val repo=StockRepository(Room.databaseBuilder(app,StockDb::class.java,"stockmate.db").build().dao()); private val query=MutableStateFlow(""); private val category=MutableStateFlow("All"); val state=combine(repo.products,repo.movements,query,category){p,m,q,c->StockState(p,m,q,c)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5_000),StockState()); init { viewModelScope.launch{repo.seed()} }; fun filter(q:String,c:String){query.value=q;category.value=c}; fun add(n:String,s:String,c:String,cost:String,price:String){ if(n.isNotBlank()&&s.isNotBlank())viewModelScope.launch{repo.add(n,s,c,cost.toDoubleOrNull()?:0.0,price.toDoubleOrNull()?:0.0)} }; fun adjust(p:Product,d:Int)=viewModelScope.launch{repo.adjust(p,d)} }
class MainActivity:ComponentActivity(){ override fun onCreate(s:Bundle?){super.onCreate(s);enableEdgeToEdge();setContent{ StockMateTheme { val vm= androidx.lifecycle.viewmodel.compose.viewModel<StockViewModel>(); StockApp(vm) }}}}
@Composable fun StockMateTheme(content: @Composable () -> Unit){ MaterialTheme(colorScheme=lightColorScheme(primary=Color(0xFF063970),secondary=Color(0xFF008B68),background=Color(0xFFF7F9FC)),content=content) }
@OptIn(ExperimentalMaterial3Api::class)
@Composable fun StockApp(vm:StockViewModel){ val state by vm.state.collectAsStateWithLifecycle(); var tab by remember{mutableIntStateOf(0)}; var showAdd by remember{mutableStateOf(false)}; Scaffold(topBar={TopAppBar(title={Text(if(tab==0)"StockMate" else "Inventory")})},bottomBar={NavigationBar{listOf("Dashboard","Products","Activity").forEachIndexed{i,t->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Text((i+1).toString())},label={Text(t)})}}},floatingActionButton={if(tab==1)FloatingActionButton(onClick={showAdd=true}){Text("+")}}){ pad->Box(Modifier.padding(pad)){when(tab){0->Dashboard(state);1->Products(state,vm);else->Activity(state)};if(showAdd)AddProduct({n,s,c,cost,price->vm.add(n,s,c,cost,price);showAdd=false},{showAdd=false})}}}
@Composable fun Dashboard(s:StockState){ val stock=s.products.sumOf{it.quantity}; val value=s.products.sumOf{it.quantity*it.cost}; LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Business overview",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Products",s.products.size.toString(),Modifier.weight(1f));Metric("Units",stock.toString(),Modifier.weight(1f))}};item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Low stock",s.products.count{it.quantity<=it.lowStockAt}.toString(),Modifier.weight(1f));Metric("Value","$%.0f".format(value),Modifier.weight(1f))}};item{Text("Stock by category",style=MaterialTheme.typography.titleMedium)};items(s.products.groupBy{it.category}.entries.toList()){(cat,products)-> val n=products.sumOf{it.quantity}; Column{Text("$cat · $n units");LinearProgressIndicator(progress={if(stock==0)0f else n.toFloat()/stock},Modifier.fillMaxWidth())}};item{Text("Recent activity",style=MaterialTheme.typography.titleMedium)};items(s.movements){Text("${it.productName}: ${if(it.delta>0)"+" else ""}${it.delta} · ${it.note}")}}}
@Composable fun Metric(label:String,value:String,modifier:Modifier=Modifier){Card(modifier){Column(Modifier.padding(14.dp)){Text(value,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(label)}}}
@Composable fun Products(s:StockState,vm:StockViewModel){var q by remember{mutableStateOf(s.query)};var cat by remember{mutableStateOf("All")}; val categories=listOf("All")+s.products.map{it.category}.distinct(); val shown=s.products.filter{(q.isBlank()||it.name.contains(q,true)||it.sku.contains(q,true))&&(cat=="All"||it.category==cat)}; LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{OutlinedTextField(q,{q=it;vm.filter(q,cat)},label={Text("Search name or SKU")},modifier=Modifier.fillMaxWidth())};item{SingleChoiceSegmentedButtonRow(Modifier.fillMaxWidth()){categories.take(3).forEachIndexed{i,c->SegmentedButton(selected=cat==c,onClick={cat=c;vm.filter(q,cat)},shape=SegmentedButtonDefaults.itemShape(i,categories.take(3).size)){Text(c)}}}};items(shown,key={it.id}){p->Card{Column(Modifier.padding(14.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Column{Text(p.name,fontWeight=FontWeight.Bold);Text("${p.sku} · ${p.category}")};AssistChip(onClick={},label={Text(if(p.quantity<=p.lowStockAt)"Low stock" else "In stock")})};Text("${p.quantity} units · Cost $${p.cost} · Sell $${p.sellingPrice}");Row{TextButton(onClick={vm.adjust(p,-1)},enabled=p.quantity>0){Text("Stock out")};TextButton(onClick={vm.adjust(p,1)}){Text("Stock in")}}}}};if(shown.isEmpty())item{Text("No products match this filter.")}}}
@Composable fun Activity(s:StockState){LazyColumn(Modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){item{Text("Movement history",style=MaterialTheme.typography.headlineSmall)};items(s.movements){Card(Modifier.fillMaxWidth()){Text("${it.productName}  ${if(it.delta>0)"+" else ""}${it.delta} — ${it.note}",Modifier.padding(14.dp))}}}}
@Composable fun AddProduct(save:(String,String,String,String,String)->Unit,cancel:()->Unit){var n by remember{mutableStateOf("")};var sku by remember{mutableStateOf("")};var cat by remember{mutableStateOf("General")};var cost by remember{mutableStateOf("")};var price by remember{mutableStateOf("")};AlertDialog(onDismissRequest=cancel,title={Text("Add product")},text={Column{OutlinedTextField(n,{n=it},label={Text("Name")});OutlinedTextField(sku,{sku=it},label={Text("SKU / barcode")});OutlinedTextField(cat,{cat=it},label={Text("Category")});OutlinedTextField(cost,{cost=it},label={Text("Cost")});OutlinedTextField(price,{price=it},label={Text("Selling price")})}},confirmButton={TextButton(onClick={save(n,sku,cat,cost,price)}){Text("Save")}},dismissButton={TextButton(onClick=cancel){Text("Cancel")}})}
